using System;using UnityEngine;using UnityEditor;using RoadGunner.ConceptArt.Editor;
public static class SavePrefabEffects {public static string Main(){foreach(string path in new[]{"Assets/RoadGunner/Prefabs/Dust Jackal.prefab","Assets/RoadGunner/Prefabs/Rust Vulture Enemy Buggy.prefab"}){var g=PrefabUtility.LoadPrefabContents(path);try{foreach(var p in g.GetComponentsInChildren<ParticleSystem>(true)){var m=p.main;if(p.name.IndexOf("dust",StringComparison.OrdinalIgnoreCase)>=0){m.startColor=new ParticleSystem.MinMaxGradient(new Color(.70f,.58f,.39f,.18f),new Color(.83f,.71f,.49f,.31f));m.maxParticles=Mathf.Min(m.maxParticles,100);m.startLifetime=new ParticleSystem.MinMaxCurve(.35f,.7f);m.startSize=new ParticleSystem.MinMaxCurve(.25f,.6f);}if(p.name.IndexOf("smoke",StringComparison.OrdinalIgnoreCase)>=0){m.startColor=new ParticleSystem.MinMaxGradient(new Color(.18f,.19f,.18f,.45f),new Color(.37f,.32f,.25f,.22f));m.maxParticles=Mathf.Min(m.maxParticles,60);}}PrefabUtility.SaveAsPrefabAsset(g,path);}finally{PrefabUtility.UnloadPrefabContents(g);}}AssetDatabase.SaveAssets();return "Shared vehicle and buggy dust/smoke also updated for future instances";}}
